
import streamlit as st
import requests

# -------------------- PAGE CONFIGURATION --------------------

st.set_page_config(
    page_title="DataSage",
    page_icon="📊",
    layout="wide"
)

API_BASE_URL = "https://datasage-multi-agent-orchestration-for.onrender.com"
API_URL = f"{API_BASE_URL}/chat"
DOWNLOAD_URL = f"{API_BASE_URL}/download"

# Files generated by the ETL agent
ETL_FILES = {
    "Extracted Data": "data/extract/extracted_data.csv",
    "Transformed Data": "data/transform/transformed_data.csv"
}


# -------------------- SESSION INITIALIZATION --------------------

if "chats" not in st.session_state:
    st.session_state.chats = {"Chat 1": []}

if "current_chat" not in st.session_state:
    st.session_state.current_chat = "Chat 1"

if "chat_counter" not in st.session_state:
    st.session_state.chat_counter = 1

if "last_route" not in st.session_state:
    st.session_state.last_route = None

if "etl_downloads" not in st.session_state:
    st.session_state.etl_downloads = {}

if "etl_file_status" not in st.session_state:
    st.session_state.etl_file_status = {}


# -------------------- SIDEBAR --------------------

with st.sidebar:

    st.title("📊 DataSage")
    st.caption("Multi-Agent Data Platform")

    st.divider()

    # Create a new conversation
    if st.button("➕ New Chat", use_container_width=True):

        st.session_state.chat_counter += 1

        new_chat = f"Chat {st.session_state.chat_counter}"

        st.session_state.chats[new_chat] = []
        st.session_state.current_chat = new_chat
        st.session_state.last_route = None

        st.rerun()

    # Select an existing conversation
    st.subheader("Your Conversations")

    st.selectbox(
        "Select Chat",
        options=list(st.session_state.chats.keys()),
        key="current_chat"
    )

    # Clear current conversation
    if st.button("🗑️ Clear Current Chat", use_container_width=True):

        st.session_state.chats[st.session_state.current_chat] = []
        st.session_state.last_route = None

        st.rerun()

    st.divider()

    # Latest routing information
    st.subheader("Agent Status")

    if st.session_state.last_route == "sql":

        st.success("SQL Analyst")
        st.caption("Handling database queries")

    elif st.session_state.last_route == "etl":

        st.info("ETL Analyst")
        st.caption("Handling data extraction and transformation")

    else:

        st.caption("Waiting for your first query...")

    # -------------------- ETL DOWNLOADS --------------------

    st.divider()

    st.subheader("📁 ETL Downloads")

    st.caption("Download files generated by the ETL agent.")

    if st.button("🔄 Refresh Available Files", use_container_width=True):

        st.session_state.etl_downloads = {}
        st.session_state.etl_file_status = {}

        with st.spinner("Checking generated files..."):

            for label, file_path in ETL_FILES.items():

                try:

                    response = requests.get(
                        DOWNLOAD_URL,
                        params={"file_path": file_path},
                        timeout=60
                    )

                    if response.status_code == 200:

                        st.session_state.etl_downloads[label] = (
                            response.content
                        )

                        st.session_state.etl_file_status[label] = "available"

                    elif response.status_code == 404:

                        st.session_state.etl_file_status[label] = "not_found"

                    else:

                        st.session_state.etl_file_status[label] = (
                            f"error_{response.status_code}"
                        )

                except requests.exceptions.RequestException:

                    st.session_state.etl_file_status[label] = "connection_error"

        st.rerun()

    # Display download buttons
    for label, file_path in ETL_FILES.items():

        status = st.session_state.etl_file_status.get(label)

        if status == "available":

            filename = file_path.split("/")[-1]

            st.download_button(
                label=f"⬇️ {label}",
                data=st.session_state.etl_downloads[label],
                file_name=filename,
                mime="text/csv",
                use_container_width=True,
                key=f"download_{label}"
            )

        elif status == "not_found":

            st.caption(f"⚪ {label}: File not found")

        elif status == "connection_error":

            st.caption(f"⚠️ {label}: Backend connection failed")

        elif status and status.startswith("error_"):

            st.caption(f"⚠️ {label}: Download error ({status})")


# -------------------- MAIN APPLICATION --------------------

st.title("📊 DataSage")

st.caption("Your Intelligent Multi-Agent Data Platform")

st.divider()


# Get messages for the selected conversation
messages = st.session_state.chats[st.session_state.current_chat]


# -------------------- DISPLAY CHAT HISTORY --------------------

for message in messages:

    with st.chat_message(message["role"]):

        st.markdown(message["content"])

        if message["role"] == "assistant" and message.get("route_used"):

            route = message["route_used"]

            if route == "sql":
                st.caption("🔍 Handled by SQL Analyst")

            elif route == "etl":
                st.caption("⚙️ Handled by ETL Analyst")


# -------------------- CHAT INPUT --------------------

user_question = st.chat_input(
    "Ask DataSage anything about your data..."
)


if user_question:

    messages.append({
        "role": "user",
        "content": user_question
    })

    with st.chat_message("user"):
        st.markdown(user_question)

    with st.chat_message("assistant"):

        with st.spinner("DataSage is thinking..."):

            try:

                response = requests.post(
                    API_URL,
                    json={"message": user_question},
                    timeout=120
                )

                response.raise_for_status()

                result = response.json()

                answer = result["response"]
                route_used = result["route_used"]

                st.session_state.last_route = route_used

                st.markdown(answer)

                if route_used == "sql":
                    st.caption("🔍 Handled by SQL Analyst")

                elif route_used == "etl":
                    st.caption("⚙️ Handled by ETL Analyst")

                messages.append({
                    "role": "assistant",
                    "content": answer,
                    "route_used": route_used
                })

            except requests.exceptions.RequestException as e:

                error_message = f"Backend connection failed: {e}"

                st.error(error_message)

                messages.append({
                    "role": "assistant",
                    "content": error_message
                })

    st.rerun()
